const searchable=(x)=>[x.fabricante,x.categoria,x.referencia,x.descripcion,...Object.values(x.atributos)].join(' ').toLocaleLowerCase('es');
const all=()=>records.slice();
function get(brand,ref){return records.find(x=>x.fabricante===brand&&x.referencia===ref)||null;}
function search(term='',brand='',category=''){
 const q=String(term).trim().toLocaleLowerCase('es');
 return records.filter(x=>(!brand||x.fabricante===brand)&&(!category||x.categoria===category)&&(!q||searchable(x).includes(q)));
}
function stats(list=records){
 const brand={},category={};for(const r of list){brand[r.fabricante]=(brand[r.fabricante]||0)+1;category[r.categoria]=(category[r.categoria]||0)+1;}
 return {total:list.length,brand,category,iva_confirmado:list.filter(x=>x.iva_base==='sin_iva_confirmado'&&x.pvp_sin_iva_eur!==null).length,
  iva_pendiente:list.filter(x=>x.iva_base!=='sin_iva_confirmado'&&x.precio_publicado_eur!==null).length,
  sin_precio:list.filter(x=>x.precio_publicado_eur===null).length};
}
function priceLabel(x){
 if(x.precio_publicado_eur===null)return 'Precio pendiente';
 const p=x.precio_publicado_eur.toLocaleString('es-ES',{style:'currency',currency:'EUR'});
 return x.iva_base==='sin_iva_confirmado'?p+' · sin IVA':p+' · IVA no confirmado';
}
root.PanelCommercial=Object.freeze({all,get,search,stats,priceLabel,fecha_captura:'2026-10-15',version:'enclosures-apparatus-sample-20261015'});
